-- Immutable, server-written evidence of acknowledgement of the published Bridge documents.
-- This migration is intended for isolated STAGING verification only.
create schema if not exists private;

create table if not exists private.bridge_legal_consents (
  id uuid primary key default gen_random_uuid(),
  auth_user_id uuid not null references auth.users(id) on delete restrict,
  document_key text not null check (document_key in ('terms', 'privacy')),
  document_version text not null,
  document_sha256 text not null check (document_sha256 ~ '^[0-9a-f]{64}$'),
  accepted_at timestamptz not null default clock_timestamp(),
  acceptance_method text not null default 'authenticated_checkbox'
    check (acceptance_method = 'authenticated_checkbox'),
  created_at timestamptz not null default clock_timestamp()
);

create index if not exists bridge_legal_consents_user_document_idx
  on private.bridge_legal_consents (auth_user_id, document_key, accepted_at desc);

alter table private.bridge_legal_consents enable row level security;
revoke all on private.bridge_legal_consents from public, anon, authenticated;

create or replace function private.prevent_bridge_legal_consent_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Legal consent evidence is immutable';
end;
$$;

drop trigger if exists bridge_legal_consents_immutable on private.bridge_legal_consents;
create trigger bridge_legal_consents_immutable
before update or delete on private.bridge_legal_consents
for each row execute function private.prevent_bridge_legal_consent_mutation();

revoke all on function private.prevent_bridge_legal_consent_mutation() from public, anon, authenticated;

-- Narrow the title-owner SECURITY DEFINER helper to the non-API schema.
-- Preserve the four existing owner policies and their authorization predicate.
-- The public wrapper remains present for rollback but is no longer executable by API roles.

create or replace function private.bridge_is_title_owner(p_title_id text)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog
set row_security = off
as $bridge_owner$
  select exists (
    select 1
    from public.bridge_titles as t
    join public.bridge_loop_identity_links as l
      on l.bridge_user_id = t.owner_user_id
    where t.id = p_title_id
      and l.auth_user_id = (select auth.uid())
  );
$bridge_owner$;

revoke all on function private.bridge_is_title_owner(text) from public;
grant usage on schema private to authenticated;
grant execute on function private.bridge_is_title_owner(text) to authenticated;

drop policy if exists bridge_production_assets_owner_select on public.bridge_production_assets;
create policy bridge_production_assets_owner_select
  on public.bridge_production_assets
  for select to authenticated
  using (private.bridge_is_title_owner(title_id));

drop policy if exists bridge_production_assets_owner_insert on public.bridge_production_assets;
create policy bridge_production_assets_owner_insert
  on public.bridge_production_assets
  for insert to authenticated
  with check (private.bridge_is_title_owner(title_id));

drop policy if exists bridge_production_assets_owner_update on public.bridge_production_assets;
create policy bridge_production_assets_owner_update
  on public.bridge_production_assets
  for update to authenticated
  using (private.bridge_is_title_owner(title_id))
  with check (private.bridge_is_title_owner(title_id));

drop policy if exists bridge_production_assets_owner_delete on public.bridge_production_assets;
create policy bridge_production_assets_owner_delete
  on public.bridge_production_assets
  for delete to authenticated
  using (private.bridge_is_title_owner(title_id));

revoke all on function public.bridge_is_title_owner(text) from public, anon, authenticated;

CREATE SCHEMA IF NOT EXISTS private;

CREATE OR REPLACE FUNCTION private.bridge_is_title_owner(p_title_id text)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog
SET row_security = off
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.bridge_titles AS t
    JOIN public.bridge_loop_identity_links AS l
      ON l.bridge_user_id = t.owner_user_id
    WHERE t.id = p_title_id
      AND l.auth_user_id = (SELECT auth.uid())
  );
$function$;

REVOKE ALL ON FUNCTION private.bridge_is_title_owner(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.bridge_is_title_owner(text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.bridge_is_title_owner(text) FROM authenticated, anon, PUBLIC;

DROP POLICY IF EXISTS bridge_production_assets_owner_select ON public.bridge_production_assets;
CREATE POLICY bridge_production_assets_owner_select
ON public.bridge_production_assets
FOR SELECT TO authenticated
USING (private.bridge_is_title_owner(title_id));

DROP POLICY IF EXISTS bridge_production_assets_owner_insert ON public.bridge_production_assets;
CREATE POLICY bridge_production_assets_owner_insert
ON public.bridge_production_assets
FOR INSERT TO authenticated
WITH CHECK (private.bridge_is_title_owner(title_id));

DROP POLICY IF EXISTS bridge_production_assets_owner_update ON public.bridge_production_assets;
CREATE POLICY bridge_production_assets_owner_update
ON public.bridge_production_assets
FOR UPDATE TO authenticated
USING (private.bridge_is_title_owner(title_id))
WITH CHECK (private.bridge_is_title_owner(title_id));

DROP POLICY IF EXISTS bridge_production_assets_owner_delete ON public.bridge_production_assets;
CREATE POLICY bridge_production_assets_owner_delete
ON public.bridge_production_assets
FOR DELETE TO authenticated
USING (private.bridge_is_title_owner(title_id));
